"use client"

import * as React from "react"
import { Sheet, type DetentSpec } from "scrollsheet"

import { cn } from "@/lib/utils"

function Drawer({ ...props }: React.ComponentProps<typeof Sheet.Root>) {
  return <Sheet.Root data-slot="drawer" {...props} />
}

function DrawerTrigger({
  ...props
}: React.ComponentProps<typeof Sheet.Trigger>) {
  return <Sheet.Trigger data-slot="drawer-trigger" {...props} />
}

function DrawerContent({
  className,
  children,
  ...props
}: React.ComponentProps<typeof Sheet.Content>) {
  return (
    <Sheet.Content
      data-slot="drawer-content"
      className={cn("bg-background rounded-t-2xl shadow-lg", className)}
      {...props}
    >
      {children}
    </Sheet.Content>
  )
}

function DrawerHandle({
  className,
  ...props
}: React.ComponentProps<typeof Sheet.Handle>) {
  return (
    <Sheet.Handle
      data-slot="drawer-handle"
      className={cn("bg-muted mx-auto mt-4 h-2 w-[100px] shrink-0 rounded-full", className)}
      {...props}
    />
  )
}

function DrawerTitle({
  className,
  ...props
}: React.ComponentProps<typeof Sheet.Title>) {
  return (
    <Sheet.Title
      data-slot="drawer-title"
      className={cn("text-foreground px-4 pt-3 font-semibold", className)}
      {...props}
    />
  )
}

function DrawerDescription({
  className,
  ...props
}: React.ComponentProps<typeof Sheet.Description>) {
  return (
    <Sheet.Description
      data-slot="drawer-description"
      className={cn("text-muted-foreground px-4 text-sm", className)}
      {...props}
    />
  )
}

function DrawerClose({
  className,
  ...props
}: React.ComponentProps<typeof Sheet.Close>) {
  return (
    <Sheet.Close
      data-slot="drawer-close"
      className={cn(
        "text-foreground/70 hover:text-foreground absolute top-4 right-4 text-sm underline-offset-4 hover:underline",
        className
      )}
      {...props}
    />
  )
}

export {
  Drawer,
  DrawerTrigger,
  DrawerContent,
  DrawerHandle,
  DrawerTitle,
  DrawerDescription,
  DrawerClose,
  type DetentSpec,
}
